/* Versioned little-endian save, bounded parser, CRC32 and recoverable replacement. */
#include "adventure.h"
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <errno.h>
typedef struct {uint8_t *out;const uint8_t *in;size_t at,size;int ok;} Codec;
static uint32_t CRC(const uint8_t *p,size_t n){uint32_t c=~0u;size_t i;unsigned b;for(i=0;i<n;i++){c^=p[i];for(b=0;b<8;b++)c=(c>>1)^(0xedb88320u&-(c&1));}return ~c;}
static uint64_t Value(Codec *c,uint64_t v,unsigned bytes){unsigned i;uint64_t r=0;if(!c->ok||bytes>c->size-c->at){c->ok=0;return 0;}for(i=0;i<bytes;i++){if(c->out)c->out[c->at]=(uint8_t)(v>>(8*i));else r|=(uint64_t)c->in[c->at]<<(8*i);c->at++;}return c->out?v:r;}
#define FIELD(x,n) do {if(c->out)Value(c,(uint64_t)(x),n);else (x)=Value(c,0,n);} while(0)
static void Mon(Codec *c,AdventureMon *m){unsigned i;FIELD(m->dex,2);FIELD(m->hp,2);FIELD(m->level,1);FIELD(m->xp,4);FIELD(m->status,4);for(i=0;i<4;i++){FIELD(m->moves[i],2);FIELD(m->pp[i],1);}}
static void Profile(Codec *c,AdventureSave *s,unsigned version){unsigned i;for(i=0;i<11;i++)FIELD(s->name[i],1);FIELD(s->appearance.body,1);for(i=0;i<6;i++)FIELD(s->appearance.option[i],1);FIELD(s->appearance.follower,1);FIELD(s->partyCount,1);FIELD(s->boxCount,1);FIELD(s->map,1);FIELD(s->step,1);FIELD(s->starter,1);FIELD(s->badges,1);FIELD(s->champion,1);FIELD(s->balls,2);FIELD(s->potions,2);FIELD(s->money,2);FIELD(s->x,4);FIELD(s->y,4);FIELD(s->playTicks,4);FIELD(s->random,4);FIELD(s->visited,8);for(i=0;i<62;i++){FIELD(s->seen[i],1);FIELD(s->caught[i],1);}for(i=0;i<6;i++)Mon(c,&s->party[i]);for(i=0;i<ADVENTURE_BOX;i++)Mon(c,&s->box[i]);if(version>=2){FIELD(s->appearance.base,1);FIELD(s->appearance.hairColour,1);FIELD(s->appearance.outfitColour,1);}}
#undef FIELD
static int ValidMon(const AdventureMon *m){unsigned i;if(!m->dex||m->dex>493||!m->level||m->level>100||m->xp>1000000000u||m->status>255)return 0;CombatFighterConfig config=Adventure_Config(m);if(m->hp>config.hp)return 0;for(i=0;i<4;i++)if(m->moves[i]>467||m->pp[i]>(m->moves[i]?Combat_GetMoveInfo(m->moves[i])->pp:0))return 0;return m->moves[0]!=0;}
int Adventure_SaveValid(const AdventureSave *s){unsigned i;if(!s||!s->name[0]||s->name[10]||s->appearance.body>1||s->appearance.follower>1||s->appearance.base>=ADV_TRAINER_BASE_COUNT||s->appearance.hairColour>=ADVENTURE_HAIR_COLOURS||s->appearance.outfitColour>=ADVENTURE_OUTFIT_COLOURS||((s->appearance.base==ADV_TRAINER_RED||s->appearance.base==ADV_TRAINER_BRENDAN)&&s->appearance.body)||s->partyCount>6||s->boxCount>ADVENTURE_BOX||s->map>=ADVENTURE_MAPS||s->step>ADVENTURE_EVENTS||s->starter>2||s->champion>1||s->balls>999||s->potions>999||s->x<0||s->x>=512*256||s->y<0||s->y>=384*256||s->visited>>ADVENTURE_MAPS)return 0;if(!s->partyCount&&s->step>2)return 0;if(s->champion&&s->step!=ADVENTURE_EVENTS)return 0;for(i=0;i<10&&s->name[i];i++)if((unsigned char)s->name[i]<32||(unsigned char)s->name[i]>126)return 0;for(i=0;i<6;i++)if(s->appearance.option[i]>=Adventure_AppearanceCount(&s->appearance,i))return 0;for(i=0;i<s->partyCount;i++)if(!ValidMon(&s->party[i]))return 0;for(i=0;i<s->boxCount;i++)if(!ValidMon(&s->box[i]))return 0;return 1;}
int Adventure_SaveEncode(const AdventureSave *s,uint8_t *out,size_t cap,size_t *written){AdventureSave copy;Codec c={out,0,16,cap,1};uint32_t crc;unsigned i;if(!out||cap<16||!Adventure_SaveValid(s))return 0;memset(out,0,cap);memcpy(out,"PA3S",4);out[4]=2;copy=*s;Profile(&c,&copy,2);if(!c.ok)return 0;crc=CRC(out+16,c.at-16);for(i=0;i<4;i++){out[8+i]=(uint8_t)(c.at>>(i*8));out[12+i]=(uint8_t)(crc>>(i*8));}if(written)*written=c.at;return 1;}
int Adventure_SaveDecode(AdventureSave *s,const uint8_t *in,size_t n){AdventureSave temp;Codec c={0,in,16,n,1};uint32_t declared=0,crc=0;unsigned i;if(!s||!in||n<16||n>ADVENTURE_SAVE_BYTES||memcmp(in,"PA3S",4)||(in[4]!=1&&in[4]!=2)||in[5]||in[6]||in[7])return 0;for(i=0;i<4;i++){declared|=(uint32_t)in[8+i]<<(i*8);crc|=(uint32_t)in[12+i]<<(i*8);}if(declared!=n||crc!=CRC(in+16,n-16))return 0;memset(&temp,0,sizeof(temp));Profile(&c,&temp,in[4]);if(!c.ok||c.at!=n||!Adventure_SaveValid(&temp))return 0;*s=temp;return 1;}
static int ReadOne(const char *path,AdventureSave *s){uint8_t bytes[ADVENTURE_SAVE_BYTES+1];FILE *f=fopen(path,"rb");size_t n;int bad;if(!f)return 0;n=fread(bytes,1,sizeof(bytes),f);bad=ferror(f);fclose(f);return !bad&&Adventure_SaveDecode(s,bytes,n);}
int Adventure_SaveRead(const char *path,AdventureSave *s){char backup[512];if(!path||strlen(path)>500)return 0;if(ReadOne(path,s))return 1;snprintf(backup,sizeof(backup),"%s.bak",path);return ReadOne(backup,s)?2:0;}
int Adventure_SaveWrite(const char *path,const AdventureSave *s){uint8_t bytes[ADVENTURE_SAVE_BYTES];size_t n;char temporary[512],backup[512];AdventureSave check;FILE *f;int good,oldGood;if(!path||strlen(path)>500||!Adventure_SaveEncode(s,bytes,sizeof(bytes),&n))return 0;snprintf(temporary,sizeof(temporary),"%s.tmp",path);snprintf(backup,sizeof(backup),"%s.bak",path);f=fopen(temporary,"wb");if(!f)return 0;good=fwrite(bytes,1,n,f)==n;if(fflush(f))good=0;if(fclose(f))good=0;if(!good||!ReadOne(temporary,&check)){remove(temporary);return 0;}oldGood=ReadOne(path,&check);if(oldGood){remove(backup);if(rename(path,backup)){remove(temporary);return 0;}}else remove(path);if(rename(temporary,path)){if(oldGood)rename(backup,path);remove(temporary);return 0;}return 1;}
